create extension if not exists pgcrypto;
create table if not exists destinations(id uuid primary key default gen_random_uuid(),canonical_identifier text unique not null,name text not null,country text,region text,administrative_areas jsonb not null default '[]',latitude double precision,longitude double precision,timezone text,languages jsonb not null default '[]',country_code text,aliases jsonb not null default '[]',boundary_geojson jsonb,metropolitan_area text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists research_profiles(id uuid primary key default gen_random_uuid(),destination_query text not null,travel_start date,travel_end date,traveller_count int not null default 1,profile jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists research_runs(id uuid primary key default gen_random_uuid(),research_profile_id uuid references research_profiles(id) on delete cascade,destination_id uuid references destinations(id),status text not null default 'queued',research_version text not null default '0.1.0',algorithm_version text not null default '0.1.0',provider_versions jsonb not null default '{}',plan jsonb not null default '{}',coverage jsonb not null default '{}',statistics jsonb not null default '{}',warnings jsonb not null default '[]',started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists research_jobs(id uuid primary key default gen_random_uuid(),research_run_id uuid not null references research_runs(id) on delete cascade,stage text not null,status text not null default 'queued',payload jsonb not null default '{}',result jsonb not null default '{}',attempts int not null default 0,available_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,error text);
create table if not exists research_job_attempts(id uuid primary key default gen_random_uuid(),research_job_id uuid not null references research_jobs(id) on delete cascade,attempt_no int not null,started_at timestamptz not null default now(),completed_at timestamptz,status text not null,error text,metadata jsonb not null default '{}');
create table if not exists research_raw_results(id uuid primary key default gen_random_uuid(),research_run_id uuid not null references research_runs(id) on delete cascade,provider text not null,provider_place_id text,request_id text,request_parameters jsonb not null default '{}',requested_fields jsonb not null default '[]',raw_response jsonb not null,provider_version text,retrieved_at timestamptz not null default now());
create table if not exists places(id uuid primary key default gen_random_uuid(),canonical_key text unique not null,destination_id uuid references destinations(id),name text not null,aliases jsonb not null default '[]',latitude double precision,longitude double precision,address jsonb not null default '{}',neighbourhood text,primary_category text,secondary_categories jsonb not null default '[]',interest_vector jsonb not null default '{}',quality_signals jsonb not null default '{}',accessibility jsonb not null default '{}',price_info jsonb not null default '{}',reservation_requirements jsonb not null default '{}',visit_duration jsonb not null default '{}',universal_score double precision,confidence double precision not null default 0.5,status text not null default 'active',metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists place_provider_ids(id uuid primary key default gen_random_uuid(),place_id uuid not null references places(id) on delete cascade,provider text not null,provider_place_id text not null,provider_url text,unique(provider,provider_place_id));
create table if not exists place_attributes(id uuid primary key default gen_random_uuid(),place_id uuid not null references places(id) on delete cascade,attribute_key text not null,value jsonb not null,source text,confidence double precision not null default 0.5,is_derived boolean not null default false,model_version text);
create table if not exists place_facts(id uuid primary key default gen_random_uuid(),place_id uuid not null references places(id) on delete cascade,fact_type text not null,original_value jsonb,resolved_value jsonb,source text,source_type text,retrieved_at timestamptz not null default now(),valid_from timestamptz,valid_until timestamptz,confidence double precision not null default 0.5,is_derived boolean not null default false,model_version text);
create table if not exists place_sources(id uuid primary key default gen_random_uuid(),place_id uuid references places(id) on delete cascade,source text not null,source_type text not null,source_url text,retrieved_at timestamptz not null default now(),validity jsonb not null default '{}',confidence double precision not null default 0.5,original_value jsonb,resolved_value jsonb);
create table if not exists place_hours(id uuid primary key default gen_random_uuid(),place_id uuid not null references places(id) on delete cascade,day_of_week int,opens time,closes time,valid_from date,valid_until date,is_exception boolean not null default false,source text,confidence double precision not null default 0.5);
create table if not exists place_events(id uuid primary key default gen_random_uuid(),destination_id uuid references destinations(id),place_id uuid references places(id) on delete cascade,external_id text,name text not null,location jsonb not null default '{}',starts_at timestamptz,ends_at timestamptz,category text,source text,source_url text,confidence double precision not null default 0.5,availability text,relevance double precision,metadata jsonb not null default '{}');
create table if not exists place_media(id uuid primary key default gen_random_uuid(),place_id uuid not null references places(id) on delete cascade,media_type text not null,url text not null,source text,width int,height int,metadata jsonb not null default '{}');
create table if not exists place_scores(id uuid primary key default gen_random_uuid(),place_id uuid not null references places(id) on delete cascade,research_run_id uuid references research_runs(id) on delete cascade,score_type text not null,score double precision not null,components jsonb not null default '{}',algorithm_version text not null,unique(place_id,research_run_id,score_type));
create table if not exists place_relationships(id uuid primary key default gen_random_uuid(),from_place_id uuid not null references places(id) on delete cascade,to_place_id uuid not null references places(id) on delete cascade,relationship_type text not null,distance_m double precision,walking_minutes int,transit_minutes int,driving_minutes int,metadata jsonb not null default '{}',unique(from_place_id,to_place_id,relationship_type));
create table if not exists taxonomy_categories(id uuid primary key default gen_random_uuid(),parent_id uuid references taxonomy_categories(id),slug text unique not null,name text not null,category_type text not null,attributes jsonb not null default '{}');
create table if not exists taxonomy_provider_mappings(id uuid primary key default gen_random_uuid(),provider text not null,external_category text not null,taxonomy_category_id uuid not null references taxonomy_categories(id) on delete cascade,confidence double precision not null default 0.8,unique(provider,external_category));
create table if not exists research_snapshots(id uuid primary key default gen_random_uuid(),research_run_id uuid unique not null references research_runs(id) on delete cascade,destination_id uuid references destinations(id),snapshot_version text not null,trip_context jsonb not null default '{}',coverage jsonb not null default '{}',provider_information jsonb not null default '{}',warnings jsonb not null default '[]',statistics jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists research_snapshot_places(snapshot_id uuid not null references research_snapshots(id) on delete cascade,place_id uuid not null references places(id) on delete cascade,relevance_score double precision,universal_score double precision,confidence double precision,hard_constraints jsonb not null default '[]',soft_constraints jsonb not null default '{}',primary key(snapshot_id,place_id));
create table if not exists cache_entries(cache_key text primary key,namespace text not null,value jsonb not null,expires_at timestamptz,provider text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_places_destination on places(destination_id);
create index if not exists idx_jobs_run_status on research_jobs(research_run_id,status);
create index if not exists idx_raw_run on research_raw_results(research_run_id);
